#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)
#define THREAD_PRIORITY K_PRIO_PREEMPT(10)

/* Data structures for FIFO items */
struct data_item {
    sys_snode_t node;
    uint32_t value;
};

struct data_item_ext {
    sys_snode_t node;
    uint32_t value;
    uint32_t extra_data[4];
};

/* FIFOs */
K_FIFO_DEFINE(fifo1);
K_FIFO_DEFINE(fifo2);

/* Semaphores for synchronization */
static struct k_sem test_sem;
static struct k_sem consumer_sem;
static struct k_sem producer_sem;

/* Thread stacks */
static K_THREAD_STACK_DEFINE(consumer_stack, STACK_SIZE);
static K_THREAD_STACK_DEFINE(producer_stack, STACK_SIZE);
static K_THREAD_STACK_DEFINE(isr_producer_stack, STACK_SIZE);

/* Thread IDs */
static k_tid_t consumer_tid;
static k_tid_t producer_tid;
static k_tid_t isr_producer_tid;

/* Data items for testing */
static struct data_item item1 = {.value = 1};
static struct data_item item2 = {.value = 2};
static struct data_item item3 = {.value = 3};
static struct data_item item4 = {.value = 4};
static struct data_item item5 = {.value = 5};

static struct data_item_ext item_ext1 = {.value = 10, .extra_data = {1, 2, 3, 4}};
static struct data_item_ext item_ext2 = {.value = 20, .extra_data = {5, 6, 7, 8}};

/* Test data for multiple producers/consumers */
#define NUM_ITEMS 10
static struct data_item multi_items[NUM_ITEMS];
static uint32_t received_values[NUM_ITEMS];
static volatile int received_count;

/* Helper function to initialize data items */
static void init_multi_items(void)
{
    for (int i = 0; i < NUM_ITEMS; i++) {
        multi_items[i].value = i + 1;
    }
    received_count = 0;
    memset(received_values, 0, sizeof(received_values));
}

/* Consumer thread for basic tests */
void consumer_thread(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    struct data_item *data;

    k_sem_give(&consumer_sem); /* Signal that consumer is ready */

    data = k_fifo_get(&fifo1, K_FOREVER);
    zassert_equal(data, &item1, "Expected item1");
    zassert_equal(data->value, 1, "Expected value 1");

    data = k_fifo_get(&fifo1, K_FOREVER);
    zassert_equal(data, &item2, "Expected item2");
    zassert_equal(data->value, 2, "Expected value 2");

    data = k_fifo_get(&fifo1, K_NO_WAIT);
    zassert_is_null(data, "Expected no item");

    k_sem_give(&test_sem); /* Signal completion */
}

/* Producer thread for basic tests */
void producer_thread(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_sem_give(&producer_sem); /* Signal that producer is ready */

    k_fifo_put(&fifo1, &item1);
    k_fifo_put(&fifo1, &item2);

    k_sem_give(&test_sem); /* Signal completion */
}

/* ISR producer thread for testing k_fifo_put_isr */
void isr_producer_thread(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_sem_give(&producer_sem); /* Signal that ISR producer is ready */

    /* Simulate an ISR context */
    k_fifo_put_isr(&fifo1, &item3);
    k_fifo_put_isr(&fifo1, &item4);

    k_sem_give(&test_sem); /* Signal completion */
}

/* Consumer thread for multiple producers/consumers */
void multi_consumer_thread(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    struct data_item *data;

    while (true) {
        data = k_fifo_get(&fifo2, K_FOREVER);
        if (data == NULL) {
            break; /* Test completion signal */
        }
        received_values[received_count++] = data->value;
        if (received_count == NUM_ITEMS) {
            break;
        }
    }
    k_sem_give(&test_sem);
}

/* Producer thread for multiple producers/consumers */
void multi_producer_thread(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    for (int i = 0; i < NUM_ITEMS; i++) {
        k_fifo_put(&fifo2, &multi_items[i]);
        k_msleep(10); /* Give consumer a chance to run */
    }
    k_sem_give(&test_sem);
}

/* Test cases */

ZTEST_USER(fifo_usage, test_fifo_basic)
{
    k_sem_init(&test_sem, 0, 1);
    k_sem_init(&consumer_sem, 0, 1);
    k_sem_init(&producer_sem, 0, 1);

    k_fifo_init(&fifo1);

    consumer_tid = k_thread_create(&consumer_tid, consumer_stack,
                                   K_THREAD_STACK_SIZEOF(consumer_stack),
                                   consumer_thread, NULL, NULL, NULL,
                                   THREAD_PRIORITY, 0, K_NO_WAIT);

    producer_tid = k_thread_create(&producer_tid, producer_stack,
                                   K_THREAD_STACK_SIZEOF(producer_stack),
                                   producer_thread, NULL, NULL, NULL,
                                   THREAD_PRIORITY, 0, K_NO_WAIT);

    k_sem_take(&consumer_sem, K_FOREVER); /* Wait for consumer to be ready */
    k_sem_take(&producer_sem, K_FOREVER); /* Wait for producer to be ready */

    k_sem_take(&test_sem, K_FOREVER); /* Wait for consumer to finish */
    k_sem_take(&test_sem, K_FOREVER); /* Wait for producer to finish */

    k_thread_abort(consumer_tid);
    k_thread_abort(producer_tid);

    /* Verify remaining items (should be none) */
    zassert_is_null(k_fifo_get(&fifo1, K_NO_WAIT), "FIFO should be empty");
}

ZTEST_USER(fifo_usage, test_fifo_put_isr)
{
    k_sem_init(&test_sem, 0, 1);
    k_sem_init(&producer_sem, 0, 1);

    k_fifo_init(&fifo1);

    isr_producer_tid = k_thread_create(&isr_producer_tid, isr_producer_stack,
                                       K_THREAD_STACK_SIZEOF(isr_producer_stack),
                                       isr_producer_thread, NULL, NULL, NULL,
                                       THREAD_PRIORITY, 0, K_NO_WAIT);

    k_sem_take(&producer_sem, K_FOREVER); /* Wait for ISR producer to be ready */
    k_sem_take(&test_sem, K_FOREVER); /* Wait for ISR producer to finish */

    k_thread_abort(isr_producer_tid);

    struct data_item *data;
    data = k_fifo_get(&fifo1, K_NO_WAIT);
    zassert_equal(data, &item3, "Expected item3");
    zassert_equal(data->value, 3, "Expected value 3");

    data = k_fifo_get(&fifo1, K_NO_WAIT);
    zassert_equal(data, &item4, "Expected item4");
    zassert_equal(data->value, 4, "Expected value 4");

    zassert_is_null(k_fifo_get(&fifo1, K_NO_WAIT), "FIFO should be empty");
}

ZTEST_USER(fifo_usage, test_fifo_peek)
{
    k_fifo_init(&fifo1);

    k_fifo_put(&fifo1, &item1);
    k_fifo_put(&fifo1, &item2);

    struct data_item *data;

    data = k_fifo_peek_head(&fifo1);
    zassert_equal(data, &item1, "Expected item1 at head");
    zassert_equal(data->value, 1, "Expected value 1 at head");

    data = k_fifo_peek_tail(&fifo1);
    zassert_equal(data, &item2, "Expected item2 at tail");
    zassert_equal(data->value, 2, "Expected value 2 at tail");

    data = k_fifo_get(&fifo1, K_NO_WAIT);
    zassert_equal(data, &item1, "Expected item1 after get");

    data = k_fifo_peek_head(&fifo1);
    zassert_equal(data, &item2, "Expected item2 at head after get");

    k_fifo_get(&fifo1, K_NO_WAIT); /* Get item2 */
    zassert_is_null(k_fifo_peek_head(&fifo1), "FIFO should be empty after all gets");
}

ZTEST_USER(fifo_usage, test_fifo_purge)
{
    k_fifo_init(&fifo1);

    k_fifo_put(&fifo1, &item1);
    k_fifo_put(&fifo1, &item2);
    k_fifo_put(&fifo1, &item3);

    zassert_not_is_null(k_fifo_peek_head(&fifo1), "FIFO should not be empty");

    k_fifo_purge(&fifo1);

    zassert_is_null(k_fifo_peek_head(&fifo1), "FIFO should be empty after purge");
}

ZTEST_USER(fifo_usage, test_fifo_timeout)
{
    k_fifo_init(&fifo1);

    struct data_item *data;
    int64_t start_time, end_time;

    start_time = k_uptime_get();
    data = k_fifo_get(&fifo1, K_MSEC(100));
    end_time = k_uptime_get();

    zassert_is_null(data, "Expected timeout, no item");
    zassert_true((end_time - start_time) >= 90 && (end_time - start_time) <= 110,
                 "Expected timeout duration around 100ms");

    k_fifo_put(&fifo1, &item1);
    data = k_fifo_get(&fifo1, K_MSEC(100));
    zassert_equal(data, &item1, "Expected item1, no timeout");
}

ZTEST_USER(fifo_usage, test_fifo_multi_producer_consumer)
{
    k_sem_init(&test_sem, 0, 1);
    k_fifo_init(&fifo2);

    init_multi_items();

    consumer_tid = k_thread_create(&consumer_tid, consumer_stack,
                                   K_THREAD_STACK_SIZEOF(consumer_stack),
                                   multi_consumer_thread, NULL, NULL, NULL,
                                   THREAD_PRIORITY, 0, K_NO_WAIT);

    producer_tid = k_thread_create(&producer_tid, producer_stack,
                                   K_THREAD_STACK_SIZEOF(producer_stack),
                                   multi_producer_thread, NULL, NULL, NULL,
                                   THREAD_PRIORITY, 0, K_NO_WAIT);

    k_sem_take(&test_sem, K_FOREVER); /* Wait for consumer to finish */
    k_sem_take(&test_sem, K_FOREVER); /* Wait for producer to finish */

    k_thread_abort(consumer_tid);
    k_thread_abort(producer_tid);

    /* Verify received items */
    zassert_equal(received_count, NUM_ITEMS, "Not all items received");
    for (int i = 0; i < NUM_ITEMS; i++) {
        zassert_equal(received_values[i], i + 1, "Received item value mismatch");
    }
    zassert_is_null(k_fifo_get(&fifo2, K_NO_WAIT), "FIFO should be empty");
}

ZTEST_SUITE(fifo_usage, NULL, NULL, NULL, NULL, NULL);
